struct AccessPolicy {                            // Policy: pure decision
    virtual Decision decide(const SecurityContext&, Action, const Resource&) const = 0;
    virtual ~AccessPolicy() = default;
};
template <class Resource> class Guard {          // Guard: enforcement point
    const AccessPolicy& policy_;
public:
    explicit Guard(const AccessPolicy& p) : policy_(p) {}
    void check(Action a, const Resource& r, const SecurityContext& ctx) const {
        if (policy_.decide(ctx, a, r) != Decision::Allow) throw AccessDenied{};
    }
};

