using Policy = std::function<Decision(const SecurityContext&, Action, const Resource&)>;
class Guard {
    Policy policy_;
public:
    explicit Guard(Policy p) : policy_(std::move(p)) {}
    void operator()(Action a, const Resource& r, const SecurityContext& ctx) const {
        if (policy_(ctx, a, r) != Decision::Allow) throw AccessDenied{};
    }
};

struct ReadOnlyPolicy {
    static Decision decide(const SecurityContext&, Action a, const Resource&) {
        return a == Action::Read ? Decision::Allow : Decision::Deny;
    }
};
template <class Policy> class Guard {
public:
    void check(Action a, const Resource& r, const SecurityContext& ctx) const {
        if (Policy::decide(ctx, a, r) != Decision::Allow) throw AccessDenied{};
    }
};
